import{_ as e,o as s,c as t,a0 as n}from"./chunks/framework.B_k70FqT.js";const g=JSON.parse('{"title":"LiteGraph 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1795867940000}'),o={name:"guide/introduction.md"};function d(p,a,i,r,c,l){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="litegraph-是什么" tabindex="-1">LiteGraph 是什么 <a class="header-anchor" href="#litegraph-是什么" aria-label="Permalink to &quot;LiteGraph 是什么&quot;">​</a></h1><p>LiteGraph 是一个用 TypeScript 编写的<strong>节点图引擎</strong>：节点、插槽与连线绘制在 HTML5 Canvas 上，整张图可以被编辑、执行与序列化。它既是可视化编辑器（拖拽节点、连线、改属性），也是一个纯数据流运行时（在浏览器或 Node 中直接跑图，不需要画布）。</p><p>本仓库是 <a href="https://github.com/jagenjo/litegraph.js" target="_blank" rel="noreferrer">jagenjo/litegraph.js</a> 的 TypeScript 重写版本（并参考了 <a href="https://github.com/space-nuko/litegraph.ts" target="_blank" rel="noreferrer">space-nuko/litegraph.ts</a>），拆成了 pnpm monorepo：<strong>核心引擎 + 可插拔节点包 + 示例应用 + 文档站</strong>。与上游相比，这里的节点包是独立的 npm 包，可以按需安装；类型检查开启了 <code>strict</code>；构建产物同时提供 ESM、UMD 与 <code>.d.ts</code>。</p><h2 id="它能做什么" tabindex="-1">它能做什么 <a class="header-anchor" href="#它能做什么" aria-label="Permalink to &quot;它能做什么&quot;">​</a></h2><ul><li><strong>可视化脚本</strong>：把业务逻辑拆成节点图，让非程序员在浏览器里连线和调参。</li><li><strong>数据/信号流编辑</strong>：音频处理链、MIDI 生成、数学运算、字符串处理等内置节点可以直接组合。</li><li><strong>实时界面</strong>：<code>live_mode</code> 隐藏编辑器的网格、边框与插槽，只保留节点自绘内容，适合做仪表盘或控制面板。</li><li><strong>图即配置</strong>：<code>graph.serialize()</code> 得到纯 JSON，可以存数据库、随应用分发，或作为插件格式。</li><li><strong>嵌入任意 Web 应用</strong>：只需要一个 <code>&lt;canvas&gt;</code> 和一个容器元素；核心包不隐式依赖样式，样式通过 <code>style.css</code> 子路径显式引入。</li></ul><h2 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LiteGraph（全局注册表 + 配置）</span></span>
<span class="line"><span>├── LGraph            一张图：节点、连线、分组、输入输出、执行循环、序列化</span></span>
<span class="line"><span>│   ├── LGraphNode    节点基类：插槽、widget、属性、序列化、onExecute 等回调</span></span>
<span class="line"><span>│   ├── LLink         连线</span></span>
<span class="line"><span>│   └── LGraphGroup   画布上的分组框</span></span>
<span class="line"><span>├── LGraphCanvas      画布：事件、渲染、UI（三个 mixin 拼装成一个类）</span></span>
<span class="line"><span>│   ├── DragAndScale  视口缩放与平移</span></span>
<span class="line"><span>│   └── ContextMenu   右键菜单</span></span>
<span class="line"><span>└── 内建节点           GraphInput、GraphOutput、Subgraph</span></span></code></pre></div><p>几个关键设计：</p><ul><li><strong>注册表模式</strong>：节点类型在运行时注册到 <code>LiteGraph.registered_node_types</code>。<code>LiteGraph.use(install)</code> 负责安装一个节点包并去重，<code>LiteGraph.registerNodeType()</code> 负责单个注册、补全 <code>category</code> 与默认标题。因此节点包之间互不 import，只依赖 core。</li><li><strong>类 + interface 声明合并 + <code>applyMixins</code></strong>：<code>LGraphCanvas</code> 把事件、渲染、UI 三个文件里的原型方法混入自身，避免 42 个手写包装方法；类型层面仍然是一个完整的类。</li><li><strong>数据流 + 事件流</strong>：普通插槽通过 <code>getInputData()</code> / <code>setOutputData()</code> 传递值；类型为 <code>event</code>（<code>BuiltInSlotType.EVENT</code>）的插槽传递动作，触发 <code>onAction</code>。</li><li><strong>执行顺序</strong>：<code>LGraph.computeExecutionOrder()</code> 按连线依赖做拓扑排序；<code>graph.start()</code> 每帧对可执行节点依次调用 <code>onExecute</code>，<code>graph.stop()</code> 结束循环。</li><li><strong>两套画布</strong>：<code>LGraphCanvas</code> 内部维护背景层与交互层两个 canvas，<code>draw()</code> 时先绘制背景再绘制前景，避免每帧重绘静态内容。</li></ul><h2 id="包矩阵" tabindex="-1">包矩阵 <a class="header-anchor" href="#包矩阵" aria-label="Permalink to &quot;包矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>说明</th><th>节点数</th></tr></thead><tbody><tr><td><code>@gausszhou/litegraph-core</code></td><td>引擎核心：注册表、图、节点、画布、连线、分组、子图、内建 graph 节点</td><td>3</td></tr><tr><td><code>@gausszhou/litegraph</code></td><td>聚合包：安装全部节点包，并重新导出 core 的全部 API 与样式</td><td>—</td></tr><tr><td><code>@gausszhou/litegraph-nodes-basic</code></td><td>常量、watch、reroute、时间、比较、数组取值</td><td>16</td></tr><tr><td><code>@gausszhou/litegraph-nodes-math</code></td><td>数学运算、取整、随机、近似相等</td><td>5</td></tr><tr><td><code>@gausszhou/litegraph-nodes-logic</code></td><td>与/或/非、比较、分支、选择器</td><td>8</td></tr><tr><td><code>@gausszhou/litegraph-nodes-strings</code></td><td>字符串拼接、JSON 解析/序列化、比较、替换</td><td>12</td></tr><tr><td><code>@gausszhou/litegraph-nodes-events</code></td><td>定时器、延迟、过滤、日志、分支</td><td>10</td></tr><tr><td><code>@gausszhou/litegraph-nodes-input</code></td><td>手柄输入</td><td>1</td></tr><tr><td><code>@gausszhou/litegraph-nodes-widget</code></td><td>按钮、开关、滑块、旋钮、进度条、面板等控件节点</td><td>10</td></tr><tr><td><code>@gausszhou/litegraph-nodes-graphics</code></td><td>曲线绘图</td><td>1</td></tr><tr><td><code>@gausszhou/litegraph-nodes-audio</code></td><td>振荡器、滤波器、延迟、混响、示波器等 Web Audio 节点</td><td>17</td></tr><tr><td><code>@gausszhou/litegraph-nodes-midi</code></td><td>MIDI 输入/输出、生成、量化、移调</td><td>12</td></tr></tbody></table><p>核心 3 个内建节点是 <code>graph/input</code>、<code>graph/output</code> 与 <code>graph/subgraph</code>；10 个节点包合计 92 个节点，总共 <strong>95 个节点类型</strong>。完整清单见<a href="/litegraph/docs/nodes/">节点目录</a>。</p><h2 id="仓库结构" tabindex="-1">仓库结构 <a class="header-anchor" href="#仓库结构" aria-label="Permalink to &quot;仓库结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/</span></span>
<span class="line"><span>  core/            引擎核心（不依赖任何节点包）</span></span>
<span class="line"><span>  litegraph/       聚合包（core + 全部节点包）</span></span>
<span class="line"><span>  nodes-basic/     ┐</span></span>
<span class="line"><span>  nodes-math/      │</span></span>
<span class="line"><span>  nodes-logic/     │</span></span>
<span class="line"><span>  nodes-strings/   ├ 10 个节点包，每个只依赖 core</span></span>
<span class="line"><span>  nodes-events/    │</span></span>
<span class="line"><span>  nodes-input/     │</span></span>
<span class="line"><span>  nodes-widget/    │</span></span>
<span class="line"><span>  nodes-graphics/  │</span></span>
<span class="line"><span>  nodes-audio/     │</span></span>
<span class="line"><span>  nodes-midi/      ┘</span></span>
<span class="line"><span>  tests/           跨包测试：核心路径、节点契约、交互、示例快照</span></span>
<span class="line"><span>apps/</span></span>
<span class="line"><span>  editor/          完整 Demo 编辑器（工具栏、示例下拉、小窗、live mode）</span></span>
<span class="line"><span>  example-minimal/ 最小集成示例</span></span>
<span class="line"><span>docs/              VitePress 文档站</span></span>
<span class="line"><span>scripts/           构建/校验/文档生成脚本</span></span></code></pre></div><h2 id="适用边界" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界" aria-label="Permalink to &quot;适用边界&quot;">​</a></h2><p>LiteGraph 只负责「图」本身：节点管理、连线、执行调度、画布交互与序列化。以下内容需要你自己提供或由节点实现：</p><ul><li>节点的业务逻辑（<code>onExecute</code>、<code>onDrawForeground</code>、<code>onAction</code> 等回调）；</li><li>具体渲染后端（核心只有 Canvas2D；<code>enableWebGL()</code> 目前是空实现，见<a href="/litegraph/docs/guide/contributing.html#路线图">路线图</a>）；</li><li>持久化与权限（序列化结果是 JSON，存哪里、谁能改由应用决定）；</li><li>无头运行时的 DOM 依赖：core 入口不会隐式访问 <code>window</code>，但 <code>LGraphCanvas</code> 仍然需要 DOM。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/litegraph/docs/guide/getting-started.html">快速开始</a>：5 分钟跑起编辑器或最小示例。</li><li><a href="/litegraph/docs/guide/packages.html">包与导入方式</a>：按需引入 core、单个节点包或聚合包。</li><li><a href="/litegraph/docs/nodes/">节点目录</a>：95 个节点类型的输入、输出、控件与属性。</li><li><a href="/litegraph/docs/api/">API 参考</a>：由源码生成的公开 API 文档。</li></ul>`,19)])])}const u=e(o,[["render",d]]);export{g as __pageData,u as default};
